  const usersQuery = useUsers();
  const [filters, setFilters] = useState({ role: '', search: '' });

  const filteredUsers = useMemo(() => {
    const users = usersQuery.data?.data ?? [];
    return users.filter((u) => {
      if (filters.role && u.role !== filters.role) return false;
      if (filters.search) {
        const lower = filters.search.toLowerCase();
        if (
          !u.firstName.toLowerCase().includes(lower) &&
          !u.lastName.toLowerCase().includes(lower) &&
          !u.email.toLowerCase().includes(lower)
        ) {
          return false;
        }
      }
      return true;
    });
  }, [usersQuery.data?.data, filters.role, filters.search]);

  const handleExport = () => {
    const header = 'Name,Email,Role,Joined\n';
    const rows = filteredUsers
      .map((u) => {
        const name = `"${u.firstName} ${u.lastName}"`;
        const email = `"${u.email}"`;
        const role = u.role;
        const joined = `"${formatDate(u.createdAt)}"`;
        return `${name},${email},${role},${joined}`;
      })
      .join('\n');
    const csv = header + rows;
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'users.csv';
    link.click();
    URL.revokeObjectURL(url);
  };

  if (usersQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const users = usersQuery.data?.data;

  if (!users) return null;

  return (
    <div className="space-y-4">
      <Form
        id="users-filters"
        onSubmit={() => {}}
        schema={z.object({ role: z.string(), search: z.string() })}
      >
        {(form) => (
          <div className="flex items-end gap-4">
            <div className="flex-1">
              <Select
                label="Filter by Role"
                options={[
                  { label: 'All Roles', value: '' },
                  { label: 'Admin', value: 'ADMIN' },
                  { label: 'User', value: 'USER' },
                ]}
                defaultValue={filters.role}
                onChange={(e) =>
                  setFilters((prev) => ({ ...prev, role: e.target.value }))
                }
                registration={form.register('role')}
              />
            </div>
            <div className="flex-1">
              <Input
                label="Search by Name or Email"
                placeholder="Search..."
                value={filters.search}
                onChange={(e) =>
                  setFilters((prev) => ({ ...prev, search: e.target.value }))
                }
                registration={form.register('search')}
              />
            </div>
            <Button
              variant="outline"
              icon={<Download className="size-4" />}
              onClick={handleExport}
            >
              Export CSV
            </Button>
          </div>
        )}
      </Form>
      <Table
        data={filteredUsers}
        columns={[
          {
            title: 'First Name',
            field: 'firstName',
          },
          {
            title: 'Last Name',
            field: 'lastName',
          },
          {
            title: 'Email',
            field: 'email',
          },
          {
            title: 'Role',
            field: 'role',
          },
          {
            title: 'Created At',
            field: 'createdAt',
            Cell({ entry: { createdAt } }) {
              return <span>{formatDate(createdAt)}</span>;
            },
          },
          {
            title: '',
            field: 'id',
            Cell({ entry: { id } }) {
              return <DeleteUser id={id} />;
            },
          },
        ]}
      />
    </div>
  );
};
```

